import WebSocketManager from '../websocket/websocket-manager';
var gStrWS2PlayerVersion = 'r2.3.1027.2024';
/* if h264cpumode is true, h264 will force use cpu.
    huawei camera h264 GPU can't work with chrome.
*/
/*
huawei h264 chrome GPU will cache 5 frame for each GOP, if insert next I frame, all the 5 frame will callback :(, there is a big jitter for render, if add a jitter buffer for rendering, buffer more than 4 frame GPU buffer, GPU will stop decoding.
*/
export class H5sPlayerWS2 {
    constructor(config) {
        console.log('[WS2] version', gStrWS2PlayerVersion);
        this.config = config;
        this._strPosterUri;
        this._debug = true;
        if (this.config.consolelog !== undefined) {
            if (this.config.consolelog === 'false') {
                this._debug = false;
            }
        }
        this._videoId = this.config.videoid;
        if (this._videoId === undefined && this._videodom != undefined) {
            this._videodom = this.config.videodom;
            if (this._debug === true)
                console.log("[WS2] use dom directly", this.config.token);
        }
        else if (this._videoId != undefined) {
            this._videodom = document.getElementById(this._videoId);
            if (this._debug === true)
                console.log("[WS2] use videoid", this.config.token);
        }
        //playback don't use poster
        if (this.config.pbconf != undefined && this.config.showposter == 'false' && this._videodom != undefined) {
            this._strPosterUri = this.config.protocol + '//' + this.config.host + this.config.rootpath +
                'api/v1/GetLoadingImage?' + 'session=' + this.config.session
                + '&refresh=' + Math.floor(Math.random() * 1000000);
            if (this._debug === true)
                console.log("[WS2] connect src", config.token);
            this._videodom.setAttribute('poster', this._strPosterUri);
        }
        else if (this._videodom != undefined) {
            this._strPosterUri = this.config.protocol + '//' + this.config.host + this.config.rootpath +
                'api/v1/GetImage?token=' + this.config.token + '&session=' + this.config.session
                + '&refresh=' + Math.floor(Math.random() * 1000000);
            if (this._debug === true)
                console.log("[WS2] connect src", config.token);
            this._videodom.setAttribute('poster', this._strPosterUri);
        }
        //this.messageHandler = new MessageHandler(this.eventEmitter);
    }
    connect() {
        var h5spath = "api/v1/h5slinkweb";
        if (this._debug === true)
            console.log("[WS2] API path", h5spath);
        //var token = this.video.getAttribute('token');
        var streamprofile = 'main';
        if (this.config.streamprofile === undefined) { }
        else {
            streamprofile = this.config.streamprofile;
        }
        var strHevc = "false";
        var mimeCodec = 'video/mp4; codecs="hev1.1.6.L93.B0, mp4a.40.2"';
        //var mimeCodec = 'video/mp4; codecs="avc1.42E01E, mp4a.40.2"';
        if ('MediaSource' in window && MediaSource.isTypeSupported(mimeCodec)) {
            if (this._debug === true)
                console.log('[WS2] MIME type or codec: ', mimeCodec);
            strHevc = "true";
        }
        else {
            if (this._debug === true)
                console.log('[WS2] Unsupported MIME type or codec: ', mimeCodec);
            strHevc = "false";
        }
        if (this.config.pbconf === undefined && this.config.mp4writerconf === undefined) {
            h5spath = this.config.rootpath + h5spath + "?token=" + this.config.token
                + "&hevc=" + strHevc + "&meta=" + this.config.meta
                + "&profile=" + streamprofile + '&session=' + this.config.session;
        }
        else if (this.config.pbconf !== undefined && this.config.mp4writerconf === undefined) {
            var serverpb = 'false';
            var filename = 'fake';
            if (this.config.pbconf.serverpb === undefined) { }
            else {
                serverpb = this.config.pbconf.serverpb;
            }
            if (this.config.pbconf.filename === undefined) { }
            else {
                filename = this.config.pbconf.filename;
            }
            var moveto = this.config.pbconf.begintime;
            if (this.config.pbconf.moveto === undefined) { }
            else {
                moveto = this.config.pbconf.moveto;
            }
            h5spath = this.config.rootpath + h5spath + "?token=" + this.config.token
                + "&playback=true"
                + "&hevc=" + strHevc
                + "&profile=" + streamprofile
                + "&serverpb=" + serverpb
                + "&begintime=" + encodeURIComponent(this.config.pbconf.begintime) //this._pbconf.begintime
                + "&endtime=" + encodeURIComponent(this.config.pbconf.endtime) //this._pbconf.endtime
                + "&moveto=" + encodeURIComponent(moveto)
                + "&filename=" + filename //file name
                + '&session=' + this.config.session;
        }
        else {
            var serverpb = 'false';
            var filename = 'fake';
            if (this.config.mp4writerconf.serverpb === undefined) { }
            else {
                serverpb = this.config.mp4writerconf.serverpb;
            }
            var moveto = this.config.mp4writerconf.begintime;
            h5spath = this.config.rootpath + h5spath + "?token=" + this.config.token
                + "&playback=true"
                + "&hevc=" + strHevc
                + "&profile=" + streamprofile
                + "&serverpb=" + serverpb
                + "&begintime=" + encodeURIComponent(this.config.mp4writerconf.begintime) //this._pbconf.begintime
                + "&endtime=" + encodeURIComponent(this.config.mp4writerconf.endtime) //this._pbconf.endtime
                + "&moveto=" + encodeURIComponent(moveto)
                + "&filename=" + filename //file name
                + '&session=' + this.config.session;
        }
        let url;
        if (this.config.protocol == "http:") {
            url = 'ws://' + this.config.host + h5spath;
        }
        if (this.config.protocol == "https:") {
            url = 'wss://' + this.config.host + h5spath;
        }
        if (this._debug === true)
            console.log("[WS2] connect to url ", url);
        this.webSocketManager = new WebSocketManager(this.config, this._videodom);
        this.webSocketManager.connect(url);
    }
    disconnect() {
        if (this._debug === true)
            console.log('[WS2] disconnect');
        this.webSocketManager.disconnect();
        this.webSocketManager = null;
    }
    start() {
        this.webSocketManager.start();
    }
    pause() {
        this.webSocketManager.pause();
    }
    resume() {
        this.webSocketManager.resume();
    }
    seek(nTime) {
        this.webSocketManager.seek(nTime);
    }
    moveto(strTime) {
        this.webSocketManager.moveto(strTime);
    }
    speed(nSpeed) {
        this.webSocketManager.speed(nSpeed);
    }
    getStatus() {
        if (this.webSocketManager) {
            return this.webSocketManager.getStatus();
        }
    }
}
