import { CodecType, VideoStreamType, VideoFrameType } from '../type';
import { Muxer, ArrayBufferTarget } from "mp4-muxer";
export default class Mp4Writer {
    constructor(debug, mp4WriterConf) {
        this.firstVTimestamp = null;
        this.firstATimestamp = null;
        this.startTime = null;
        this.endTime = null;
        this.mp4WriterEnable = true;
        this.mp4Name = null;
        this.mp4WriterConf = null;
        this.currentTimestamp = null;
        this.totalBytesReceived = 0;
        if (debug)
            console.log("mp4writer", mp4WriterConf);
        this._debug = debug;
        this.mp4WriterConf = mp4WriterConf;
        this.startTime = new Date(mp4WriterConf.begintime).getTime();
        this.endTime = new Date(mp4WriterConf.endtime).getTime();
        this.mp4Name = mp4WriterConf.mp4name;
        if (this.endTime > this.startTime && mp4WriterConf.mp4writer) {
            this.mp4WriterEnable = true;
        }
    }
    handleDataReceived(payload) {
        const encodedData = new Uint8Array(payload.data);
        this.totalBytesReceived += encodedData.byteLength; // 累加收到的字节数
        if (this.mp4DateTimer != null) {
            clearTimeout(this.mp4DateTimer);
        }
        this.handleData(encodedData);
        this.mp4DateTimer = setTimeout(() => {
            if (this.mp4WriterEnable) {
                this.finish();
            }
        }, 10000);
    }
    handleData(data) {
        if (!this.mp4WriterEnable) {
            return;
        }
        const view = new DataView(data.buffer);
        const header = {
            StreamType: view.getUint32(0, false),
            FrameType: view.getUint32(4, false),
            Seq: view.getUint32(8, false),
            Secs: view.getBigUint64(12, false),
            Msecs: view.getUint32(20, false),
            DataLen: view.getUint32(24, false),
            Ptsdiff: view.getUint32(28, false),
        };
        const currentTimestamp = header.Secs * 1000n + BigInt(header.Msecs);
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_INFO && header.FrameType === VideoFrameType.VIDEO_FRM_INFO) {
            const EXTRA_MAX_SIZE = 1024 * 4; // EXTRA_MAX_SIZE 的值
            const info = {
                Video: view.getUint32(32, false),
                Width: view.getUint32(36, false),
                Height: view.getUint32(40, false),
                Fps: view.getUint32(44, false),
                vExtra: new Uint8Array(data.slice(48, 48 + EXTRA_MAX_SIZE)),
                vExtraLen: view.getUint32(48 + EXTRA_MAX_SIZE, false),
                Audio: view.getUint32(52 + EXTRA_MAX_SIZE, false),
                aSampleRate: view.getUint32(56 + EXTRA_MAX_SIZE, false),
                aSampleBit: view.getUint32(60 + EXTRA_MAX_SIZE, false),
                aChannels: view.getUint32(64 + EXTRA_MAX_SIZE, false),
                aExtra: new Uint8Array(data.slice(68 + EXTRA_MAX_SIZE, 68 + 2 * EXTRA_MAX_SIZE)),
                aExtraLen: view.getUint32(68 + 2 * EXTRA_MAX_SIZE, false),
            };
            if (this._debug === true)
                console.log(`[WS2] info data:`, info);
            if (!this.muxer) {
                this.muxer = new Muxer({
                    target: new ArrayBufferTarget(),
                    video: {
                        codec: this.getVideoCodecString(info.Video),
                        width: info.Width,
                        height: info.Height,
                    },
                    audio: {
                        codec: this.getAudioCodecString(info.Audio),
                        sampleRate: info.aSampleRate,
                        numberOfChannels: info.aChannels
                    },
                    firstTimestampBehavior: 'offset'
                });
            }
            return;
        }
        if (header.FrameType === VideoFrameType.VIDEO_FRM_I || header.FrameType === VideoFrameType.VIDEO_FRM_P || header.FrameType === VideoFrameType.VIDEO_FRM_B) {
            this.handleVodioData(header, currentTimestamp, data);
        }
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_AUDIO && header.FrameType === VideoFrameType.VIDEO_FRM_AUDIO) {
            this.handleAudioData(header, currentTimestamp, data);
        }
        return null; // No video frame to decode
    }
    // 处理音频数据
    handleAudioData(header, audioTimestamp, audioData) {
        // 计算相对时间戳
        let relativeTimestamp = BigInt(0);
        if (this.firstATimestamp == null) {
            this.firstATimestamp = audioTimestamp;
        }
        else {
            relativeTimestamp = audioTimestamp - this.firstATimestamp;
        }
        if (audioTimestamp + BigInt(1000) >= this.endTime) {
            this.finish();
            return;
        }
        // 以微秒为单位
        const relativeTimestampMicroseconds = relativeTimestamp * 1000n;
        const frameDataStart = 32;
        const frameData = audioData.subarray(frameDataStart);
        // 添加音频数据到 muxer
        try {
            const audioChunk = new EncodedAudioChunk({
                // type: this.getFrameType(header.FrameType) as EncodedAudioChunkType,
                type: "key",
                timestamp: Number(relativeTimestampMicroseconds),
                data: frameData,
            });
            this.muxer.addAudioChunk(audioChunk);
        }
        catch (error) {
            console.error('Error adding audio chunk:', error);
        }
    }
    // 处理视频数据
    handleVodioData(header, videoTimestamp, data) {
        let relativeTimestamp = BigInt(0);
        if (this.firstVTimestamp == null) {
            this.firstVTimestamp = videoTimestamp; // 第一帧的时间戳（毫秒）
            this.firstATimestamp = videoTimestamp; // 第一帧的时间戳（毫秒）
        }
        else {
            relativeTimestamp = videoTimestamp - this.firstVTimestamp; // 相对时间戳（毫秒）
        }
        if (videoTimestamp + BigInt(1000) >= this.endTime) {
            this.finish();
            return;
        }
        this.currentTimestamp = videoTimestamp;
        const relativeTimestampMicroseconds = relativeTimestamp * 1000n; // 转换成微秒
        const frameDataStart = 32;
        const frameData = data.subarray(frameDataStart);
        try {
            const chunk = new EncodedVideoChunk({
                type: this.getFrameType(header.FrameType),
                timestamp: Number(relativeTimestampMicroseconds),
                data: frameData,
                // duration: 0,
            });
            this.muxer.addVideoChunk(chunk);
        }
        catch (error) {
        }
    }
    //音频都是关键帧
    getFrameType(frameType) {
        switch (frameType) {
            case VideoFrameType.VIDEO_FRM_I:
                return 'key';
            case VideoFrameType.VIDEO_FRM_P:
            case VideoFrameType.VIDEO_FRM_B:
                return 'delta';
            default:
                return 'delta';
        }
    }
    //工具函数
    getVideoCodecString(codecType) {
        switch (codecType) {
            case CodecType.CODEC_H264:
                return 'avc';
            case CodecType.CODEC_H265:
                return 'hevc';
            case CodecType.CODEC_VP9:
                return 'vp9';
            case CodecType.CODEC_AV1:
                return 'av1';
            case CodecType.CODEC_MJPEG:
            default:
                return "avc";
        }
    }
    //工具函数
    getAudioCodecString(codecType) {
        switch (codecType) {
            case CodecType.CODEC_AAC:
                return 'aac';
            default:
                return "opus";
        }
    }
    destory() {
        let time = this.formatWithTimezoneOffset(new Date(Number(this.currentTimestamp)));
        console.log(time);
        let data = `{
        "type": "H5S_MP4_WRITER_CLOSE",
        "strTime": "${time}"
       }`;
        this.mp4WriterConf.callback(data, this.mp4WriterConf.userdata);
        this.firstVTimestamp = null;
        this.firstATimestamp = null;
        this.startTime = null;
        this.endTime = null;
        this.muxer = null;
        this.mp4WriterConf = null;
    }
    finish() {
        if (this.muxer && this.mp4WriterEnable) {
            this.mp4WriterEnable = false;
            this.muxer.finalize();
            let buffer = this.muxer.target.buffer; //读取数据缓冲区
            this.downloadBlob(new Blob([buffer]));
            this.destory();
        }
    }
    downloadBlob(blob) {
        let url = window.URL.createObjectURL(blob); //创建一个 URL
        let a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = this.mp4Name;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
    }
    //iso1608时间格式转换
    formatWithTimezoneOffset(date) {
        if (!date) {
            date = new Date();
        }
        // 获取日期的各个组成部分
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        const seconds = String(date.getSeconds()).padStart(2, '0');
        // 获取时区偏移（以分钟为单位）
        const timezoneOffset = date.getTimezoneOffset();
        const absoluteOffset = Math.abs(timezoneOffset);
        // 将偏移转换为小时和分钟
        const offsetHours = String(Math.floor(absoluteOffset / 60)).padStart(2, '0');
        const offsetMinutes = String(absoluteOffset % 60).padStart(2, '0');
        // 确定偏移的符号
        const offsetSign = timezoneOffset <= 0 ? '+' : '-';
        // 组装最终的字符串
        const formattedDate = `${year}-${month}-${day}T${hours}:${minutes}:${seconds}${offsetSign}${offsetHours}:${offsetMinutes}`;
        return formattedDate;
    }
}
