import { BaseShape } from "./baseShape";
export class Polygon extends BaseShape {
    // conf={
    //     vertices:null,
    //     id :"uuid",
    //     name:"name",
    //     borderColor:"#0399FE",
    // }
    constructor(conf = {}) {
        super();
        this.vertices = [];
        this.isHighlighted = false;
        this.isClosed = false;
        this.polygon = 0;
        this.id = conf.id || Polygon.lastId++;
        this.name = conf.name || `ID-${this.id}`;
        if (conf.vertices) {
            this.vertices = conf.vertices;
        }
    }
    setWarnEnable(warnEnable) {
        if (warnEnable) {
            this.polygon += 1;
        }
        else {
            this.polygon -= 1;
        }
        if (this.polygon > 0) {
            this.warnEnable = true;
        }
        else {
            this.polygon = 0;
            this.warnEnable = false;
        }
    }
    static setStyleConfig(styleConfig, isHighlight = false) {
        if (isHighlight) {
            Polygon.highlightStyle = { ...Polygon.highlightStyle, ...styleConfig };
        }
        else {
            Polygon.style = { ...Polygon.style, ...styleConfig };
        }
    }
    draw(ctx) {
        // 根据是否高亮来选择当前样式
        let currentStyle = this.isHighlighted ? Polygon.highlightStyle : Polygon.style;
        if (this.warnEnable) {
            currentStyle = Polygon.warnStyle;
        }
        if (this.vertices.length === 0) {
            return;
        }
        if (this.vertices.length === 1) {
            this.drawVertex(ctx, this.vertices[0], currentStyle);
            return;
        }
        ctx.beginPath();
        ctx.moveTo(this.vertices[0].x, this.vertices[0].y);
        // 遍历所有顶点，绘制线段
        for (let i = 1; i < this.vertices.length; i++) {
            ctx.lineTo(this.vertices[i].x, this.vertices[i].y);
        }
        // 当有超过两个顶点时，关闭路径并填充多边形
        if (this.vertices.length > 2) {
            ctx.closePath();
            ctx.fillStyle = currentStyle.fillColor;
            ctx.fill();
        }
        // 设置线段颜色、粗细并绘制线段
        ctx.strokeStyle = currentStyle.lineColor;
        ctx.lineWidth = currentStyle.lineWidth; // 设置线段粗细
        ctx.stroke();
        // 遍历所有顶点，绘制顶点
        for (const vertex of this.vertices) {
            this.drawVertex(ctx, vertex, currentStyle);
        }
    }
    drawVertex(ctx, vertex, style) {
        const RADIUS = style.vertexRadius;
        ctx.beginPath();
        ctx.arc(vertex.x, vertex.y, RADIUS, 0, 2 * Math.PI);
        ctx.fillStyle = "white"; // 设置为白色填充
        ctx.fill();
        ctx.strokeStyle = style.lineColor; // 设置外圈颜色与线段颜色相同
        ctx.lineWidth = 1; // 可以设置为需要的边框粗细
        ctx.stroke(); // 绘制外圈
    }
    addVertex(vertex) {
        if (this.vertices.length < 2) {
            this.vertices.push(vertex);
            return true;
        }
        else if (this.vertices.length >= 2 && !this.doesIntersect(vertex)) {
            this.vertices.push(vertex);
            return true;
        }
        return false;
    }
    doesIntersect(vertex) {
        for (let start = 0; start < this.vertices.length; start++) {
            let intersect = false;
            for (let i = 0; i < this.vertices.length - 1; i++) {
                if (i === start || i + 1 === start)
                    continue; // 跳过与新线段相邻的线段
                if (this.checkIntersect(this.vertices[start], vertex, this.vertices[i], this.vertices[i + 1])) {
                    intersect = true;
                    break;
                }
            }
            if (!intersect) {
                return false; // 找到了一个顶点与新点之间的线段不与其他任何线段相交
            }
        }
        return true; // 所有顶点与新点之间的线段都与其他线段相交
    }
    checkIntersect(p1, q1, p2, q2) {
        let o1 = this.getOrientation(p1, q1, p2);
        let o2 = this.getOrientation(p1, q1, q2);
        let o3 = this.getOrientation(p2, q2, p1);
        let o4 = this.getOrientation(p2, q2, q1);
        if (o1 !== o2 && o3 !== o4)
            return true;
        // Special Cases
        if (o1 === 0 && this.isOnSegment(p1, p2, q1))
            return true;
        if (o2 === 0 && this.isOnSegment(p1, q2, q1))
            return true;
        if (o3 === 0 && this.isOnSegment(p2, p1, q2))
            return true;
        if (o4 === 0 && this.isOnSegment(p2, q1, q2))
            return true;
        return false;
    }
    isSelfIntersecting() {
        const n = this.vertices.length;
        for (let i = 0; i < n; i++) {
            for (let j = i + 1; j < n; j++) {
                if (i !== 0 || j !== n - 1) { // 如果不是相邻的顶点
                    if (this.doIntersect(this.vertices[i], this.vertices[(i + 1) % n], this.vertices[j], this.vertices[(j + 1) % n])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
    getOrientation(p, q, r) {
        let val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
        if (val === 0)
            return 0;
        return (val > 0) ? 1 : 2;
    }
    getName() {
        return this.name;
    }
    setName(newName) {
        this.name = newName;
    }
    getID() {
        return this.id;
    }
    setHighlight(status) {
        this.isHighlighted = status;
    }
    getVertices() {
        return this.vertices;
    }
    edgeClicked(point, tolerance = 5) {
        for (let i = 0; i < this.vertices.length; i++) {
            const nextIndex = (i + 1) % this.vertices.length;
            const distance = this.distanceToSegment(point, this.vertices[i], this.vertices[nextIndex]);
            if (distance < tolerance) {
                return i;
            }
        }
        return -1;
    }
    distanceToSegment(p, v, w) {
        const l2 = Math.pow(v.x - w.x, 2) + Math.pow(v.y - w.y, 2);
        if (l2 === 0)
            return this.distance(p, v);
        let t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2;
        t = Math.max(0, Math.min(1, t));
        return this.distance(p, { x: v.x + t * (w.x - v.x), y: v.y + t * (w.y - v.y) });
    }
    distance(p1, p2) {
        return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
    }
    closePolygon() {
        this.isClosed = true;
    }
    contains(point) {
        let intersects = 0;
        for (let i = 0; i < this.vertices.length; i++) {
            let j = (i + 1) % this.vertices.length;
            if (this.doIntersect(point, { x: Number.MAX_VALUE, y: point.y }, this.vertices[i], this.vertices[j])) {
                intersects++;
            }
        }
        return intersects % 2 === 1;
    }
    doIntersect(p1, q1, p2, q2) {
        let o1 = this.getOrientation(p1, q1, p2);
        let o2 = this.getOrientation(p1, q1, q2);
        let o3 = this.getOrientation(p2, q2, p1);
        let o4 = this.getOrientation(p2, q2, q1);
        if (o1 !== o2 && o3 !== o4)
            return true;
        if (o1 === 0 && this.isOnSegment(p1, p2, q1))
            return true;
        if (o2 === 0 && this.isOnSegment(p1, q2, q1))
            return true;
        if (o3 === 0 && this.isOnSegment(p2, p1, q2))
            return true;
        if (o4 === 0 && this.isOnSegment(p2, q1, q2))
            return true;
        return false;
    }
    isOnSegment(p, q, r) {
        return q.x <= Math.max(p.x, r.x) && q.x >= Math.min(p.x, r.x) &&
            q.y <= Math.max(p.y, r.y) && q.y >= Math.min(p.y, r.y);
    }
    move(dx, dy) {
        for (let vertex of this.vertices) {
            vertex.x += dx;
            vertex.y += dy;
        }
    }
    updateVertex(index, point) {
        if (index >= 0 && index < this.vertices.length) {
            this.vertices[index] = point;
        }
    }
    deleteVertex(index) {
        if (index >= 0 && index < this.vertices.length) {
            this.vertices.splice(index, 1);
        }
    }
    isPolygonClosed() {
        return this.isClosed;
    }
    distanceToPoint(point) {
        if (this.contains(point)) {
            return 0;
        }
        let minDistance = Number.MAX_VALUE;
        for (let i = 0; i < this.vertices.length; i++) {
            let j = (i + 1) % this.vertices.length;
            let distance = this.distanceToSegment(point, this.vertices[i], this.vertices[j]);
            if (distance < minDistance) {
                minDistance = distance;
            }
        }
        return minDistance;
    }
    squaredDistance(v, w) {
        return (v.x - w.x) * (v.x - w.x) + (v.y - w.y) * (v.y - w.y);
    }
    isPointNearVertex(point, threshold = 5) {
        for (const vertex of this.vertices) {
            const distance = Math.sqrt(this.squaredDistance(point, vertex));
            if (distance < threshold) {
                return true;
            }
        }
        return false;
    }
    isPointOnEdge(point, threshold = 5) {
        for (let i = 0; i < this.vertices.length; i++) {
            let j = (i + 1) % this.vertices.length;
            const distance = this.distanceToSegment(point, this.vertices[i], this.vertices[j]);
            if (distance < threshold) {
                return true;
            }
        }
        return false;
    }
}
Polygon.lastId = 0;
Polygon.style = {
    vertexColor: "white",
    vertexRadius: 5,
    lineColor: '#00D9FF',
    fillColor: "rgba(0, 217, 255, 0.2)",
    lineWidth: 1
};
Polygon.highlightStyle = {
    vertexColor: "white",
    vertexRadius: 5,
    lineColor: '#FCFF00',
    fillColor: "rgba(255, 255, 0, 0.2)",
    lineWidth: 1
};
Polygon.warnStyle = {
    vertexColor: "white",
    vertexRadius: 5,
    lineColor: 'red',
    fillColor: "rgba(255, 0, 0, 0.2)",
    lineWidth: 1
};
