import { EventTypes } from '../event-handler/event-types';
import WebpackWorker from "worker-loader?inline=no-fallback!./worker";
import JitterBuffer from './jitter_buffer';
import AudioWorker from "worker-loader?inline=no-fallback!./audioworker";
export default class DecWorkerMgr {
    constructor(nSpeed, jbuffersize, debug, eventEmitter) {
        this.worker = new WebpackWorker();
        this.audioworker = new AudioWorker();
        this.firstTimestamp = null;
        this.audioDecoder = null;
        this.audioConfiged = false;
        // 在类内添加这些属性来跟踪帧数和时间
        this.frameCount = 0;
        this.startTime = performance.now(); // 记录开始时间
        this.timeWindow = 2000; // 设置2秒的时间窗口
        this.totalBytesReceived = 0;
        this.lastBitrateCalculationTimestamp = 0;
        this.bitrate = 0;
        this.fps = 0;
        this.freeSpace = 0;
        this.lastVideoTimestamp = null; //ms
        this.calculateBitrateTimer = null;
        this.renderingTimer = null;
        this.decodedFrameTimestamp = null;
        this.decodedFrameNum = 0;
        this.lastInputVideoTimestamp = null; //ms
        this.decingTimer = null;
        this.decJitter = null;
        this._jbuffersize = 300;
        this._nCurrentSpeed = 1.0;
        this._bJitterFistFull = false;
        //console.log("DecWorkerMgr", this);
        this._debug = debug;
        this._nCurrentSpeed = nSpeed;
        this._jbuffersize = jbuffersize - 80;
        if (this._jbuffersize <= 0) {
            this._jbuffersize = 0;
        }
        this.jitter = new JitterBuffer(80, undefined);
        if (this._jbuffersize != 0) {
            this.decJitter = new JitterBuffer(this._jbuffersize, undefined);
        }
        this.eventEmitter = eventEmitter;
        // 创建一个队列策略对象，并设置 highWaterMark
        const queuingStrategy = new CountQueuingStrategy({ highWaterMark: 5 });
        // 创建 ReadableStream，并应用这个队列策略
        this.stream = new ReadableStream({
            start: (controller) => {
                this.streamController = controller;
            }
        }, queuingStrategy);
        const audioQueuingStrategy = new CountQueuingStrategy({ highWaterMark: 10 });
        this.audioStream = new ReadableStream({
            start: (controller) => {
                this.audioStreamController = controller;
            },
            cancel: (reason) => {
                if (this._debug === true)
                    console.log('[WS2] Stream canceled due to:', reason);
            }
        }, audioQueuingStrategy);
        this.worker.onmessage = this.handleMessage.bind(this);
        this.audioworker.onmessage = this.audioHandleMessage.bind(this);
        // 将 stream 传递给 worker
        this.worker.postMessage({ debug: this._debug, stream: this.stream }, [this.stream]);
        this.audioworker.postMessage({ debug: this._debug, stream: this.audioStream }, [this.audioStream]);
        this.lastBitrateCalculationTimestamp = Date.now();
        this.calculateBitrateTimer = setInterval(this.calculateBitrate.bind(this), 2000); // 每2秒计算一次比特率
        /* disable enable render jitter  */
        //this.renderingTimer = setTimeout(this.rendering.bind(this), this.jitter.GetFristDuration()/1000);
        if (this.decJitter) {
            this.decingTimer = setTimeout(this.decing.bind(this), this.decJitter.GetFristDuration() / 1000);
        }
    }
    handleVideoDataReceived(decodeInfo) {
        if (decodeInfo) {
            let combinedDataBuffer;
            let combinedData;
            if (decodeInfo.type === 'audio') {
                // 音频数据处理
                const configJson = JSON.stringify({ config: decodeInfo.config, chunkInfo: decodeInfo.chunkInfo });
                const configBuffer = new TextEncoder().encode(configJson);
                // @ts-ignore
                const descriptionBuffer = decodeInfo.config.description;
                const totalLength = configBuffer.length + descriptionBuffer.byteLength + decodeInfo.data.byteLength + 8;
                combinedDataBuffer = new ArrayBuffer(totalLength);
                const combinedDataView = new DataView(combinedDataBuffer);
                combinedDataView.setUint32(0, configBuffer.length, true);
                combinedDataView.setUint32(4, descriptionBuffer.byteLength, true);
                new Uint8Array(combinedDataBuffer, 8, configBuffer.length).set(configBuffer);
                new Uint8Array(combinedDataBuffer, 8 + configBuffer.length, descriptionBuffer.byteLength).set(descriptionBuffer);
                new Uint8Array(combinedDataBuffer, 8 + configBuffer.length + descriptionBuffer.byteLength).set(decodeInfo.data);
                combinedData = new Uint8Array(combinedDataBuffer);
                this.audioStreamController?.enqueue(combinedData);
            }
            else if (decodeInfo.type === 'video') {
                // 视频数据处理
                const configJson = JSON.stringify({ config: decodeInfo.config, chunkInfo: decodeInfo.chunkInfo });
                const configBuffer = new TextEncoder().encode(configJson);
                const totalLength = configBuffer.length + decodeInfo.data.byteLength + 4;
                combinedDataBuffer = new ArrayBuffer(totalLength);
                const combinedDataView = new DataView(combinedDataBuffer);
                combinedDataView.setUint32(0, configBuffer.length, true);
                new Uint8Array(combinedDataBuffer, 4, configBuffer.length).set(configBuffer);
                new Uint8Array(combinedDataBuffer, 4 + configBuffer.length).set(decodeInfo.data);
                combinedData = new Uint8Array(combinedDataBuffer);
                let duration = 0;
                if (this.lastInputVideoTimestamp == null) {
                }
                else {
                    duration = decodeInfo.chunkInfo.timestamp - this.lastInputVideoTimestamp;
                }
                if (duration < 0) {
                    duration = 0;
                }
                //only speed 1 use jitter
                this.lastInputVideoTimestamp = decodeInfo.chunkInfo.timestamp;
                //console.log("decodeInfo.chunkInfo.timestamp", decodeInfo.chunkInfo.timestamp);
                if (this.decJitter && this._nCurrentSpeed <= 1 && this._nCurrentSpeed > 0) {
                    this.decJitter.AddItem({ duration: Number(duration) }, combinedData);
                }
                else {
                    this.streamController?.enqueue(combinedData);
                }
            }
        }
    }
    audioHandleMessage(event) {
        if (event.data.type === 'audiodecoded') {
            // 获取 Worker 返回的解码后的帧
            //console.log('audio decode:',event.data.audioData.timestamp)
            const decodedFrame = event.data.audioData;
            this.eventEmitter.emit(EventTypes.DECODED_AUDIO_FRAME, decodedFrame);
        }
    }
    getDecodedFrameTimestamp() {
        return this.decodedFrameTimestamp;
    }
    getDecodedFrameNum() {
        return this.decodedFrameNum;
    }
    getRenderCached() {
        return this.jitter.GetLengthMs();
    }
    getInputCached() {
        if (this.decJitter) {
            return this.decJitter.GetLengthMs();
        }
        else {
            return 0;
        }
    }
    setSpeed(nSpeed) {
        this._nCurrentSpeed = nSpeed;
        if (nSpeed < 0) {
            //backward play disable the jitter
            this._bJitterFistFull = false;
            if (this.decJitter)
                this.decJitter.Clear();
        }
        if (nSpeed > 1) {
            if (this.decJitter) {
                //loop to read from jitter 
                while (1) {
                    let combinedData = this.decJitter.GetItem();
                    //console.log("rendering orderedVideoData", orderedVideoData);
                    if (combinedData != undefined) {
                        this.streamController?.enqueue(combinedData.extraData);
                    }
                    else {
                        break;
                    }
                }
            }
        }
    }
    handleMessage(event) {
        if (event.data.type === 'decoded') {
            // 获取 Worker 返回的解码后的帧
            const decodedFrame = event.data.frame;
            //console.log('video decode',decodedFrame)
            // 确保 decodedFrame 是一个 VideoFrame 或其它可以被传输的对象
            if (decodedFrame instanceof VideoFrame || decodedFrame instanceof ArrayBuffer) {
                // 触发帧解码事件，发送给渲染模块
                const decFrame = decodedFrame;
                let duration = 0;
                if (this.lastVideoTimestamp == null) {
                }
                else {
                    duration = decFrame.timestamp - this.lastVideoTimestamp;
                }
                this.decodedFrameTimestamp = BigInt(decFrame.timestamp);
                this.decodedFrameNum++;
                this.lastVideoTimestamp = decFrame.timestamp;
                //console.log("decoded: decodedFrame.timestamp", decFrame.timestamp);
                /* disable enable render jitter  */
                //this.jitter.AddItem({duration: Number(duration)}, decodedFrame);
                this.eventEmitter.emit(EventTypes.DECODED_FRAME, decodedFrame);
                // 更新帧数
                this.frameCount++;
                // 获取当前时间
                const now = performance.now();
                const elapsedTime = now - this.startTime;
                // 检查是否已过2秒时间窗口
                if (elapsedTime >= this.timeWindow) {
                    // 计算帧率：帧数除以经过的时间（转换成秒）
                    const fps = this.frameCount / (elapsedTime / 1000);
                    this.fps = fps;
                    // console.log(`Current FPS: ${fps.toFixed(2)}`);
                    // 重置开始时间和帧数
                    this.startTime = now;
                    this.frameCount = 0;
                }
            }
            else {
                if (this._debug === true)
                    console.log('Received object is not a VideoFrame or ArrayBuffer');
            }
        }
    }
    destory() {
        clearTimeout(this.decingTimer);
        clearTimeout(this.renderingTimer);
        clearInterval(this.calculateBitrateTimer);
        // ... 其他清理工作 ...
        // 终止 Web Worker
        if (this.worker) {
            //this.worker.terminate();
            this.streamController.close();
            //console.log('Worker has been terminated.');
            this.worker = null;
        }
        if (this.audioworker) {
            //this.worker.terminate();
            this.audioStreamController.close();
            //console.log('Worker has been terminated.');
            this.audioworker = null;
        }
        // ... 其他可能的清理工作 ...
    }
    calculateBitrate() {
        const now = Date.now();
        const timeElapsed = (now - this.lastBitrateCalculationTimestamp) / 1000; // 转换为秒
        this.bitrate = (this.totalBytesReceived * 8) / timeElapsed; // 比特率 = 总比特数 / 时间
        this.totalBytesReceived = 0; // 重置计数
        this.lastBitrateCalculationTimestamp = now;
        // console.log(`Current Bitrate: ${this.bitrate} bps`);
        // 可以在此处触发一个事件将比特率发送到UI
    }
    rendering() {
        const orderedVideoData = this.jitter.GetItem();
        //console.log("rendering orderedVideoData", orderedVideoData);
        if (orderedVideoData != undefined) {
            //console.log(orderedVideoData.extraData)
            this.eventEmitter.emit(EventTypes.DECODED_FRAME, orderedVideoData.extraData);
        }
        else {
            //if(this._debug === true) console.log('rwo can not get item');
        }
        let duration = this.jitter.GetFristDuration() / 1000;
        //console.log("rendering GetFristDuration", duration);
        if (duration == 0) {
            //first frame
            const f = this.jitter.GetItem();
            //console.log(f)
            if (f != undefined) {
                this.eventEmitter.emit(EventTypes.DECODED_FRAME, f.extraData);
            }
            //console.log(this.jitter.GetFristDuration());
            this.renderingTimer = setTimeout(this.rendering.bind(this), 10);
        }
        else {
            let overLength = this.jitter.GetOverLengthMs();
            let nNextTimer = duration;
            if (overLength <= 0) {
                nNextTimer = duration;
            }
            else {
                nNextTimer = duration - (overLength / duration) * 1;
            }
            nNextTimer = nNextTimer / Math.abs(this._nCurrentSpeed);
            //console.log("rendering", duration, this.jitter.GetLengthMs(), overLength, nNextTimer);
            this.renderingTimer = setTimeout(this.rendering.bind(this), nNextTimer);
        }
    }
    decing() {
        let t1 = Date.now();
        if (this._bJitterFistFull == false) {
            /* wait for jitter buffer full then start process */
            if (this.decJitter.GetLengthMs() >= this._jbuffersize) {
                this._bJitterFistFull = true;
            }
            else {
                this.decingTimer = setTimeout(this.decing.bind(this), this.decJitter.GetFristDuration() / 1000);
                return;
            }
        }
        let combinedData = this.decJitter.GetItem();
        //console.log("rendering orderedVideoData", orderedVideoData);
        if (combinedData != undefined) {
            this.streamController?.enqueue(combinedData.extraData);
        }
        else {
            //if(this._debug === true) console.log('dwo can not get item');
        }
        let duration = this.decJitter.GetFristDuration() / 1000;
        //console.log("rendering GetFristDuration", duration);
        if (duration == 0) {
            //first frame
            const f = this.decJitter.GetItem();
            if (f != undefined) {
                this.streamController?.enqueue(f.extraData);
            }
            //console.log(this.decJitter.GetFristDuration());
            this.decingTimer = setTimeout(this.decing.bind(this), 1);
        }
        else {
            let overLength = this.decJitter.GetOverLengthMs() - 1 * duration;
            let nNextTimer = duration;
            if (overLength <= 0) {
                nNextTimer = duration;
            }
            else {
                nNextTimer = duration - (overLength / duration) * 1.5;
            }
            let t2 = Date.now();
            //t is ElapsedTime
            let t = t2 - t1;
            nNextTimer = nNextTimer - t;
            //console.log("t2 - t1", t2 - t1);
            //console.log(duration, this.decJitter.GetLengthMs(), overLength, nNextTimer);
            this.decingTimer = setTimeout(this.decing.bind(this), nNextTimer);
        }
    }
    getStatus() {
        const bitrateInt = Math.trunc(this.bitrate); // 保留整数部分
        const fpsInt = Math.trunc(this.fps); // 同样，保留整数部分
        let obj = {
            'Bitrate': bitrateInt,
            'fps': fpsInt,
            'QueueSize': this.freeSpace,
            'codec': 'H264'
        };
        return obj;
    }
    toHex(data) {
        return Array.from(data)
            .map(byte => byte.toString(16).padStart(2, '0'))
            .join(' ');
    }
}
