export default class VedDispMgrWs {
    constructor(config) {
        this.wsSocket = null;
        this.keepaliveTimerId = null;
        this.reconnectTimerId = null;
        this.lastTimeDataRecvived = null;
        this.totalDataRecvived = BigInt(0);
        this.eventEmitter = null;
        this._debug = true;
        this.config = config;
        //console.log(config)
        if (config.consolelog != undefined) {
            if (config.consolelog === 'false') {
                this._debug = false;
            }
        }
        this.bDisConnected = false;
        this.bNeedReconnect = false;
        //this.eventEmitter = new EventEmitter();
    }
    setupWebSocket(url) {
        if (this._debug === true)
            console.log('[VED mgr] start connect to:', url);
        this.wsSocket = new WebSocket(url);
        this.wsSocket.binaryType = 'arraybuffer'; // 设置 binaryType 为 'arraybuffer'
        this.wsSocket.onopen = this.handleOpen.bind(this);
        this.wsSocket.onmessage = this.handleMessage.bind(this); // handleMessage 现在可以直接处理 ArrayBuffer 数据
        this.wsSocket.onclose = this.handleClose.bind(this);
        this.wsSocket.onerror = this.handleError.bind(this);
    }
    connect(url) {
        this._url = url;
        this.setupWebSocket(url);
        this.reconnectTimerId = setInterval(this.ReconnectFunction.bind(this), 3000);
    }
    createWindows(nCount, nParent) {
        try {
            this.sendMessage({ type: 'VED_CMD_CREATE_WINDOW_REQ',
                createWindowReq: {
                    nCount: nCount,
                    nParentHandle: nParent
                }
            });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    moveWindows(moveArray, bAnimation) {
        try {
            this.sendMessage({ type: 'VED_CMD_MOVE_WINDOW_REQ',
                session: this._dispSession,
                moveWindowReq: {
                    animation: bAnimation,
                    move: moveArray
                }
            });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    showWindows(winArray) {
        try {
            this.sendMessage({ type: 'VED_CMD_SHOW_WINDOW_REQ',
                session: this._dispSession,
                winList: {
                    win: winArray
                }
            });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    hideWindows(winArray) {
        try {
            this.sendMessage({ type: 'VED_CMD_HIDE_WINDOW_REQ',
                session: this._dispSession,
                winList: {
                    win: winArray
                }
            });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    start() {
        try {
            this.sendMessage({ cmd: 'H5_START' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    pause() {
        try {
            this.sendMessage({ cmd: 'H5_PAUSE' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    resume() {
        try {
            this.sendMessage({ cmd: 'H5_RESUME' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    seek(nTime) {
        try {
            this.sendMessage({ cmd: 'H5_SEEK', nSeekTime: nTime });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    moveto(strTime) {
        try {
            this.sendMessage({ cmd: 'H5_MOVETO', strMovetoTime: strTime });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    handleMessage(event) {
        if (typeof event.data === 'string') {
            //if(this._debug === true) console.log("[WS2] string");
            if (this.config.vedconf != undefined && this.config.vedconf.callback != undefined) {
                try {
                    let msg = JSON.parse(event.data);
                    if (msg.type == 'VED_CMD_EVENT_DISPLAY_SESSION') {
                        this._dispSession = msg.session;
                    }
                }
                catch (e) {
                    if (this._debug === true)
                        console.log(e);
                }
                this.config.vedconf.callback(event.data, this.config.vedconf.userdata);
            }
            return;
        }
        if (this._debug === true)
            console.log('[VED mgr] Unexpected data type:', event.data);
    }
    sendMessage(message) {
        if (this.wsSocket && this.wsSocket.readyState === WebSocket.OPEN) {
            let msg = JSON.stringify(message);
            if (this._debug === true)
                console.log('[VED mgr] send:', msg);
            this.wsSocket.send(msg);
        }
        else {
            if (this._debug === true)
                console.log('[VED mgr] WebSocket is not open. Cannot send message:', message);
        }
    }
    disconnect() {
        this.bDisConnected = true;
        clearInterval(this.reconnectTimerId);
        if (this.wsSocket != null) {
            this.wsSocket.close();
            this.wsSocket = null;
        }
        this.cleanupKeepalive();
    }
    handleOpen(event) {
        if (this.config.pbconf != undefined && this.config.pbconf.autoplay === 'true') {
            this.start();
        }
        //console.log('ws open')
        //this.eventEmitter.emit(EventTypes.WS_OPEN, event);
        // Setup heartbeat once connection is opened
        this.setupKeepalive();
    }
    handleClose(event) {
        //this.eventEmitter.emit(EventTypes.WS_CLOSE, event);
        // Cleanup heartbeat on close
        this.cleanupKeepalive();
        if (this._debug === true)
            console.log("[VED mgr] wsSocket.onclose");
        if (this.bDisConnected === true) {
            if (this._debug === true)
                console.log("[VED mgr] wsSocket.onclose disconnect");
        }
        else {
            this.bNeedReconnect = true;
        }
    }
    handleError(event) {
        //this.eventEmitter.emit(EventTypes.WS_ERROR, event);
    }
    setupKeepalive() {
        this.keepaliveTimerId = setInterval(this.keepaliveTimer.bind(this), 5000);
    }
    keepaliveTimer() {
        if (this.lastTimeDataRecvived != null) {
            if (this.totalDataRecvived <= this.lastTimeDataRecvived) {
                if (this.config.vedconf === undefined) {
                    //live
                    if (this._debug === true)
                        console.log('[VED mgr] no data received reconnect...');
                    this.bNeedReconnect = true;
                    if (this.wsSocket) {
                        this.wsSocket.close();
                        this.wsSocket = null;
                    }
                    return;
                }
                else {
                    //playback
                }
            }
        }
        this.lastTimeDataRecvived = this.totalDataRecvived;
        try {
            this.sendMessage({ type: 'VED_CMD_KEEPALIVE_REQ',
                session: this._dispSession });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    ReconnectFunction() {
        if (this.bNeedReconnect === true) {
            if (this._debug === true)
                console.log('[VED mgr] Reconnect...');
            this.lastTimeDataRecvived = null;
            this.totalDataRecvived = BigInt(0);
            this.setupWebSocket(this._url);
            this.bNeedReconnect = false;
        }
    }
    cleanupKeepalive() {
        if (this.keepaliveTimerId !== null) {
            //console.log("cleanupKeepalive")
            clearInterval(this.keepaliveTimerId);
            this.keepaliveTimerId = null;
        }
    }
}
