export class TestVideo {
    constructor(videoElement) {
        this.videoElement = null;
        this.videoCodec = null;
        this.firstTimestamp = null;
        this.isDecoderConfigured = false;
        this.videoTrackGenerator = null;
        //音频
        this.audioDecoderConfigured = false;
        this.audioDecoder = null;
        this.audioTrackGenerator = null;
        this.audioCodec = null;
        // @ts-ignore
        this.audioWriter = null; // 新增音频写入器
        this.videoElement = videoElement;
        if (videoElement) {
            console.log('videoElement', videoElement);
            // @ts-ignore
            this.videoTrackGenerator = new MediaStreamTrackGenerator({ kind: 'video' });
            // @ts-ignore
            this.audioTrackGenerator = new MediaStreamTrackGenerator({ kind: 'audio' }); // 初始化音频轨道生成器
            console.log('videoTrackGenerator', this.videoTrackGenerator);
            const mediaStream = new MediaStream();
            mediaStream.addTrack(this.videoTrackGenerator);
            mediaStream.addTrack(this.audioTrackGenerator); // 将音频轨道添加到流中
            videoElement.srcObject = mediaStream;
        }
        this.initDecoder();
    }
    initDecoder() {
        // 检查视频解码器支持
        if ('VideoDecoder' in window) {
            this.videoDecoder = new VideoDecoder({
                output: this.handleVideoFrame.bind(this),
                error: e => console.error('Video decoder error:', e)
            });
        }
        else {
            console.error('VideoDecoder API is not supported.');
        }
        // 检查音频解码器支持
        this.audioDecoder = new AudioDecoder({
            output: this.handleAudioFrame.bind(this),
            error: e => console.error('Audio decoder error:', e)
        });
        console.log('init decoder!!!!!! ');
    }
    handleVideoFrame(frame) {
        // 把视频帧写入 videoTrackGenerator
        this.videoTrackGenerator?.write(frame);
        // 关闭视频帧以释放资源
        frame.close();
    }
    // @ts-ignore
    handleAudioFrame(frame) {
        // 把音频帧写入 audioTrackGenerator
        this.audioTrackGenerator?.write(frame);
        // 关闭音频帧以释放资源
        frame.close();
    }
    start(url) {
        console.log('start');
        this.ws = new WebSocket(url);
        this.ws.binaryType = 'arraybuffer';
        this.ws.onmessage = (event) => {
            const data = new Uint8Array(event.data);
            this.handleVideoData(data);
        };
    }
    handleVideoData(data) {
        const view = new DataView(data.buffer);
        const header = {
            StreamType: view.getUint32(0, false),
            FrameType: view.getUint32(4, false),
            Seq: view.getUint32(8, false),
            Secs: view.getBigUint64(12, false),
            Msecs: view.getUint32(20, false),
            DataLen: view.getUint32(24, false),
            Ptsdiff: view.getUint32(28, false),
        };
        if (this.firstTimestamp === null) {
            this.firstTimestamp = header.Secs * 1000n + BigInt(header.Msecs);
        }
        const relativeTimestamp = (header.Secs * 1000n + BigInt(header.Msecs)) - this.firstTimestamp;
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_INFO && header.FrameType === VideoFrameType.VIDEO_FRM_INFO) {
            const EXTRA_MAX_SIZE = 1024 * 4; // EXTRA_MAX_SIZE 的值
            const info = {
                Video: view.getUint32(32, false),
                Width: view.getUint32(36, false),
                Height: view.getUint32(40, false),
                Fps: view.getUint32(44, false),
                vExtra: new Uint8Array(data.slice(48, 48 + EXTRA_MAX_SIZE)),
                vExtraLen: view.getUint32(48 + EXTRA_MAX_SIZE, false),
                Audio: view.getUint32(52 + EXTRA_MAX_SIZE, false),
                aSampleRate: view.getUint32(56 + EXTRA_MAX_SIZE, false),
                aSampleBit: view.getUint32(60 + EXTRA_MAX_SIZE, false),
                aChannels: view.getUint32(64 + EXTRA_MAX_SIZE, false),
                aExtra: new Uint8Array(data.slice(68 + EXTRA_MAX_SIZE, 68 + 2 * EXTRA_MAX_SIZE)),
                aExtraLen: view.getUint32(68 + 2 * EXTRA_MAX_SIZE, false),
                // padding 字段通常不需要解析
            };
            console.log('INFO DATA', info);
            this.aSampleRate = info.aSampleRate;
            this.aChannels = info.aChannels;
            this.audioCodec = this.getCodecString(info.Audio);
            this.videoCodec = this.getCodecString(info.Video);
            this.audioDecoder.configure({
                codec: this.audioCodec,
                sampleRate: this.aSampleRate,
                numberOfChannels: this.aChannels, // 使用硬编码的通道数
            });
            return;
        }
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_AUDIO &&
            header.FrameType === VideoFrameType.VIDEO_FRM_AUDIO) {
            // console.log('音频',this.toHex(data))
            // @ts-ignore
            const audioChunk = new EncodedAudioChunk({
                type: this.getFrameType(header.FrameType),
                timestamp: Number(relativeTimestamp),
                data: data // 你从网络获取的编码音频数据
            });
            // 将编码的音频数据传递给解码器
            if (this.audioDecoder) {
                this.audioDecoder.decode(audioChunk);
            }
        }
        if (this.videoCodec && (header.FrameType === VideoFrameType.VIDEO_FRM_I || header.FrameType === VideoFrameType.VIDEO_FRM_P || header.FrameType === VideoFrameType.VIDEO_FRM_B)) {
            if (this.isDecoderConfigured) {
                const frameDataStart = 32;
                const frameData = data.slice(frameDataStart);
                const frame = new EncodedVideoChunk({
                    type: this.getFrameType(header.FrameType),
                    timestamp: Number(relativeTimestamp),
                    data: frameData,
                });
                this.videoDecoder.decode(frame);
            }
        }
    }
    getCodecString(codecType) {
        //console.log('codecType', codecType);
        switch (codecType) {
            case CodecType.CODEC_PCMU:
                return 'audio/PCMU';
            case CodecType.CODEC_PCMA:
            case CodecType.CODEC_G711A:
            case CodecType.CODEC_G711U:
                return 'audio/PCMA';
            case CodecType.CODEC_H264:
                return 'avc1.42001E';
            case CodecType.CODEC_H265:
                return 'hev1.1.6.L93.B0';
            case CodecType.CODEC_MPEG4:
                return 'video/mp4; codecs=mp4v.20.8';
            case CodecType.CODEC_VP9:
                return 'video/vp9; codecs=vp09.00.10.08';
            case CodecType.CODEC_AV1:
                return 'video/av1; codecs=av01';
            case CodecType.CODEC_MJPEG:
                return 'video/jpeg; codecs=mjpa';
            case CodecType.CODEC_AAC:
                return 'mp4a.40.2';
            case CodecType.CODEC_G722:
                return 'audio/G722';
            case CodecType.CODEC_G726:
                return 'audio/G726';
            case CodecType.CODEC_OPUS:
                return 'audio/opus';
            case CodecType.CODEC_ARAW:
                return 'audio/pcm; codecs=1';
            default:
                throw new Error('Unknown codec type');
        }
    }
    getFrameType(frameType) {
        console.log('frameType', frameType);
        switch (frameType) {
            case VideoFrameType.VIDEO_FRM_I:
                return 'key';
            case VideoFrameType.VIDEO_FRM_P:
            case VideoFrameType.VIDEO_FRM_B:
                return 'delta';
            default:
                return 'delta';
        }
    }
    toHex(data) {
        return Array.from(data)
            .map(byte => byte.toString(16).padStart(2, '0'))
            .join(' ');
    }
}
