import VedDispMgrWs from '../ved/veddispmgr-ws';
var gStrVedMgrVersion = 'r1.0.1127.2024';
export class VedDispMgr {
    constructor(config) {
        this.eventEmitter = null;
        this._debug = true;
        this.config = config;
        //console.log(config)
        if (config.consolelog != undefined) {
            if (config.consolelog === 'false') {
                this._debug = false;
            }
        }
        console.log('[VED] version', gStrVedMgrVersion);
    }
    connect() {
        var h5spath = "api/v1/vedmgr";
        if (this.config.vedconf == undefined) {
            console.log("[VED mgr] vedconf undefined");
            return;
        }
        if (this._debug === true)
            console.log("[VED mgr] API path", h5spath);
        //var token = this.video.getAttribute('token');
        h5spath = this.config.rootpath + h5spath
            + '?bgcolorr=' + this.config.vedconf.bgcolorr
            + '&bgcolorg=' + this.config.vedconf.bgcolorg
            + '&bgcolorb=' + this.config.vedconf.bgcolorb
            + '&session=' + this.config.session;
        let url;
        if (this.config.protocol == "http:") {
            url = 'ws://' + this.config.host + h5spath;
        }
        if (this.config.protocol == "https:") {
            url = 'wss://' + this.config.host + h5spath;
        }
        if (this._debug === true)
            console.log("[VED mgr] connect to url ", url);
        this.ws = new VedDispMgrWs(this.config);
        this.ws.connect(url);
    }
    createWindows(nCount, nParent) {
        this.ws.createWindows(nCount, nParent);
    }
    moveWindows(moveArray, bAnimation) {
        this.ws.moveWindows(moveArray, bAnimation);
    }
    showWindows(winArray) {
        this.ws.showWindows(winArray);
    }
    hideWindows(winArray) {
        this.ws.hideWindows(winArray);
    }
    disconnect() {
        if (this._debug === true)
            console.log('[VED ply] disconnect');
        this.ws.disconnect();
        this.ws = null;
    }
}
