import DecWorkerMgr from '../decoder/decwo_mgr';
import { CodecType, VideoStreamType, VideoFrameType } from '../type';
//TODO split start worker function, if video data compare decoded data big than a GOP ?, need set restart flag, and next I frame restart worker function
//TODO jitter only for decoded data
export default class WorkerDecoder {
    constructor(nSpeed, h264cpumode, jbuffersize, debug, eventEmitter, metaconf) {
        this.metaconf = null;
        this.decWorkerMgr = null;
        this.firstVTimestamp = null;
        this.lastVTimestamp = null;
        this.firstATimestamp = null;
        this.audioDecoder = null;
        this.audioConfiged = false;
        //这里是流传输
        this.totalBytesReceived = 0;
        this.decodedFrameCheckTimer = null;
        this.currTimestampMicroseconds = null;
        this.inputVideoFrameNum = 0;
        this.bGotIframe = false;
        this._h264cpumode = false;
        this._jbuffersize = 300;
        this._nSpeed = 1.0;
        this._nCurrentSpeed = 1.0;
        this._nVideoCodec = 254;
        this.metaconf = metaconf;
        //console.log("WorkerDecoder", this);
        this._debug = debug;
        this._nSpeed = nSpeed;
        this._h264cpumode = h264cpumode;
        this._jbuffersize = jbuffersize;
        this.eventEmitter = eventEmitter;
        this.inputVideoFrameNum = 0;
        //console.log("new DecWorkerMgr");
        this.decWorkerMgr = new DecWorkerMgr(this._nCurrentSpeed, this._jbuffersize, this._debug, eventEmitter);
        this.decodedFrameCheckTimer = setInterval(this.decodedFrameCheck.bind(this), 2000); // 每2秒计算一次比特率
        //接收WS传过来的数据
        //this.eventEmitter.on('VIDEO_DATA_RECEIVED', this.handleVideoDataReceived.bind(this));
    }
    handleVideoDataReceived(payload) {
        const encodedData = new Uint8Array(payload.data);
        this.totalBytesReceived += encodedData.byteLength; // 累加收到的字节数
        const decodeInfo = this.handleVideoData(encodedData);
        if (this.decWorkerMgr) {
            this.decWorkerMgr.handleVideoDataReceived(decodeInfo);
        }
    }
    //TODO based frame diff to get relativeTimestamp
    handleVideoData(data) {
        const view = new DataView(data.buffer);
        const header = {
            StreamType: view.getUint32(0, false),
            FrameType: view.getUint32(4, false),
            Seq: view.getUint32(8, false),
            Secs: view.getBigUint64(12, false),
            Msecs: view.getUint32(20, false),
            DataLen: view.getUint32(24, false),
            Ptsdiff: view.getUint32(28, false),
        };
        let currentTimestamp = header.Secs * 1000n + BigInt(header.Msecs);
        //console.log(data);
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_INFO && header.FrameType === VideoFrameType.VIDEO_FRM_INFO) {
            const EXTRA_MAX_SIZE = 1024 * 4; // EXTRA_MAX_SIZE 的值
            const info = {
                Video: view.getUint32(32, false),
                Width: view.getUint32(36, false),
                Height: view.getUint32(40, false),
                Fps: view.getUint32(44, false),
                vExtra: new Uint8Array(data.slice(48, 48 + EXTRA_MAX_SIZE)),
                vExtraLen: view.getUint32(48 + EXTRA_MAX_SIZE, false),
                Audio: view.getUint32(52 + EXTRA_MAX_SIZE, false),
                aSampleRate: view.getUint32(56 + EXTRA_MAX_SIZE, false),
                aSampleBit: view.getUint32(60 + EXTRA_MAX_SIZE, false),
                aChannels: view.getUint32(64 + EXTRA_MAX_SIZE, false),
                aExtra: new Uint8Array(data.slice(68 + EXTRA_MAX_SIZE, 68 + 2 * EXTRA_MAX_SIZE)),
                aExtraLen: view.getUint32(68 + 2 * EXTRA_MAX_SIZE, false),
            };
            const audioCodec = this.parseAudioCodec(info.aExtra);
            //if(this._debug === true) console.log('[WS2] info', info)
            this._nVideoCodec = info.Video;
            if (this._debug === true)
                console.log(`[WS2] info data Video:${info.Video},Audio:${info.Audio}, Width:${info.Width}, Height:${info.Height}`);
            this.audioSpecificConfig = info.aExtra; // 直接使用 aExtra 作为音频特定配置
            this.codec = this.getCodecString(info.Video);
            this.audioCodec = audioCodec;
            this.aSampleRate = info.aSampleRate;
            this.aChannels = info.aChannels;
            //console.log('this.audio codec version 1', this.audioCodec)
            return;
        }
        //backward playback ingore audio
        if (this.audioCodec && header.StreamType === VideoStreamType.VIDEO_STREAM_AUDIO &&
            header.FrameType === VideoFrameType.VIDEO_FRM_AUDIO && this._nCurrentSpeed > 0) {
            let relativeTimestamp;
            if (this.firstATimestamp) {
                relativeTimestamp = currentTimestamp - this.firstATimestamp; // 相对时间戳（毫秒）
            }
            else {
                relativeTimestamp = BigInt(0);
            }
            const relativeTimestampMicroseconds = relativeTimestamp * 1000n; // 转换成微秒
            if (this.firstATimestamp == null) {
                this.firstATimestamp = currentTimestamp; // 第一帧的时间戳（毫秒）
                if (this.firstVTimestamp == null) {
                    this.firstVTimestamp = currentTimestamp; // 第一帧的时间戳（毫秒）
                }
            }
            const frameDataStart = 32;
            //32是header的字段长度
            const frameData = data.subarray(frameDataStart);
            const config = {
                codec: this.audioCodec,
                sampleRate: this.aSampleRate,
                numberOfChannels: this.aChannels,
                description: this.audioSpecificConfig
            };
            const chunkInfo = {
                type: 'key',
                timestamp: Number(relativeTimestampMicroseconds),
            };
            //console.log("audio:", relativeTimestampMicroseconds, header.Secs, header.Msecs);
            return {
                type: 'audio',
                data: frameData,
                config: config,
                chunkInfo: chunkInfo,
            };
        }
        if (this.codec && (header.FrameType === VideoFrameType.VIDEO_FRM_I || header.FrameType === VideoFrameType.VIDEO_FRM_P || header.FrameType === VideoFrameType.VIDEO_FRM_B)) {
            //set last video type
            if (this._nCurrentSpeed < 0) {
                if (this.lastVTimestamp != null) {
                    //render need the Timestamp increase
                    currentTimestamp = this.lastVTimestamp + BigInt(1);
                }
                else {
                    //first frame and backwards use currentTimestamp
                }
            }
            this.lastVTimestamp = currentTimestamp;
            //console.log("DataLen", header.DataLen);
            let relativeTimestamp;
            if (this.firstVTimestamp) {
                relativeTimestamp = currentTimestamp - this.firstVTimestamp; // 相对时间戳（毫秒）
            }
            else {
                relativeTimestamp = BigInt(0);
            }
            const relativeTimestampMicroseconds = relativeTimestamp * 1000n; // 转换成微秒
            if (this.firstVTimestamp == null) {
                this.firstVTimestamp = currentTimestamp; // 第一帧的时间戳（毫秒）
                if (this.firstATimestamp == null) {
                    this.firstATimestamp = currentTimestamp; // 第一帧的时间戳（毫秒）
                }
                // console.log('进入', this.firstTimestamp)
            }
            const frameDataStart = 32;
            const frameData = data.subarray(frameDataStart);
            let accmode = 'no-preference';
            if (this._h264cpumode == true && this._nVideoCodec == CodecType.CODEC_H264) {
                accmode = 'prefer-software';
            }
            const config = {
                codec: this.codec,
                hardwareAcceleration: accmode, //prefer-software prefer-hardware  no-preference
            };
            if (this.bGotIframe == false) {
                if (header.FrameType != VideoFrameType.VIDEO_FRM_I) {
                    return;
                }
                else {
                    this.bGotIframe = true;
                }
            }
            //worker has been deleted, I frame restart DecWorkerMgr
            if (header.FrameType === VideoFrameType.VIDEO_FRM_I && this.decWorkerMgr == null) {
                this.inputVideoFrameNum = 0;
                //console.log("new DecWorkerMgr")
                this.decWorkerMgr = new DecWorkerMgr(this._nCurrentSpeed, this._jbuffersize, this._debug, this.eventEmitter);
            }
            this.inputVideoFrameNum++;
            const chunkInfo = {
                type: this.getFrameType(header.FrameType),
                timestamp: Number(relativeTimestampMicroseconds),
            };
            this.currTimestampMicroseconds = relativeTimestampMicroseconds;
            //console.log("Input: relativeTimestampMicroseconds", relativeTimestampMicroseconds);
            return {
                type: 'video',
                data: frameData,
                config: config,
                chunkInfo: chunkInfo,
            };
        }
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_META_DATA
            && (header.FrameType === VideoFrameType.VIDEO_FRM_META_ANA
                || header.FrameType === VideoFrameType.VIDEO_FRM_META_CELL_MOTION)) {
            const frameDataStart = 32;
            const frameData = data.subarray(frameDataStart);
            var MataData = new TextDecoder().decode(frameData);
            //TODO render meta to canvas on top of video
            // console.log('[WS2] meta ', MataData)
            if (this.metaconf) {
                this.metaconf.callback(MataData);
            }
            return;
        }
        if (header.StreamType === VideoStreamType.VIDEO_STREAM_PBEVENT) {
            if (header.FrameType === VideoFrameType.VIDEO_FRM_PBSEEKED) {
                //console.log("seeked");
                this.seekedProcess();
            }
            else if (header.FrameType === VideoFrameType.VIDEO_FRM_PBSPEED) {
                //apply new speed
                this._nCurrentSpeed = this._nSpeed;
                if (this.decWorkerMgr) {
                    this.decWorkerMgr.setSpeed(this._nCurrentSpeed);
                }
            }
        }
        return null; // No video frame to decode
    }
    seekedProcess() {
        this.firstVTimestamp = null;
        this.firstATimestamp = null;
        this.bGotIframe = false;
        this.currTimestampMicroseconds = null;
        //restart decoder
        this.decWorkerMgr.destory();
        this.decWorkerMgr = null;
    }
    setSpeed(nSpeed) {
        this._nSpeed = nSpeed;
    }
    destory() {
        //console.log(this, "destory");
        clearInterval(this.decodedFrameCheckTimer);
        //this.eventEmitter.off('VIDEO_DATA_RECEIVED', this.handleVideoDataReceived.bind(this));
        if (this.decWorkerMgr) {
            this.decWorkerMgr.destory();
            this.decWorkerMgr = null;
        }
    }
    decodedFrameCheck() {
        if (this.decWorkerMgr) {
            if (this.currTimestampMicroseconds != null) {
                let diff = BigInt(0);
                if (this.decWorkerMgr.getDecodedFrameTimestamp() != null) {
                    diff = this.currTimestampMicroseconds - this.decWorkerMgr.getDecodedFrameTimestamp();
                }
                else {
                    if (this.inputVideoFrameNum > 50) {
                        if (this._debug === true)
                            console.log('[WS2] restart wo max no output frame:', this.inputVideoFrameNum);
                        this.decWorkerMgr.destory();
                        this.decWorkerMgr = null;
                        return;
                    }
                }
                let output = this.decWorkerMgr.getDecodedFrameNum();
                let ioDiff = this.inputVideoFrameNum - output;
                if (this._debug === true)
                    console.log("[WS2] dc:", Number(diff / BigInt(1000)), "rc:", this.decWorkerMgr.getRenderCached(), "input:", this.inputVideoFrameNum, "diff:", ioDiff, "ic:", this.decWorkerMgr.getInputCached());
                if (this._nCurrentSpeed > 0) {
                    if (this._nCurrentSpeed <= 4.0) {
                        if (diff / BigInt(1000) > 3000 * this._nCurrentSpeed || this.decWorkerMgr.getRenderCached() > (3000 * this._nCurrentSpeed)) {
                            if (this._debug === true)
                                console.log('[WS2] restart wo', diff / BigInt(1000));
                            this.decWorkerMgr.destory();
                            this.decWorkerMgr = null;
                        }
                    }
                }
                else {
                    //TODO back playback
                }
            }
        }
    }
    //工具函数
    getCodecString(codecType) {
        //console.log('codecType', codecType);
        switch (codecType) {
            case CodecType.CODEC_PCMU:
                return 'audio/PCMU';
            case CodecType.CODEC_PCMA:
            case CodecType.CODEC_G711A:
            case CodecType.CODEC_G711U:
                return 'audio/PCMA';
            case CodecType.CODEC_H264:
                return 'avc1.42001E';
            case CodecType.CODEC_H265:
                return 'hev1.1.6.L93.B0';
            case CodecType.CODEC_MPEG4:
                return 'video/mp4; codecs=mp4v.20.8';
            case CodecType.CODEC_VP9:
                return 'video/vp9; codecs=vp09.00.10.08';
            case CodecType.CODEC_AV1:
                return 'video/av1; codecs=av01';
            case CodecType.CODEC_MJPEG:
                return 'video/jpeg; codecs=mjpa';
            case CodecType.CODEC_AAC:
                return 'mp4a.40.2';
            case CodecType.CODEC_G722:
                return 'audio/G722';
            case CodecType.CODEC_G726:
                return 'audio/G726';
            case CodecType.CODEC_OPUS:
                return 'audio/opus';
            case CodecType.CODEC_ARAW:
                return 'audio/pcm; codecs=1';
            default:
                throw new Error('Unknown codec type');
        }
    }
    getFrameType(frameType) {
        // console.log('frameType', frameType)
        switch (frameType) {
            case VideoFrameType.VIDEO_FRM_I:
                return 'key';
            case VideoFrameType.VIDEO_FRM_P:
            case VideoFrameType.VIDEO_FRM_B:
                return 'delta';
            default:
                return 'delta';
        }
    }
    parseAudioCodec(aExtra) {
        if (aExtra.length < 2) {
            return "unknown"; // 确保 aExtra 至少有两个字节
        }
        const audioObjectType = ((aExtra[0] << 8) | aExtra[1]) >> 11;
        //console.log('audioObjectType 111', audioObjectType)
        switch (audioObjectType) {
            case 2:
                return "mp4a.40.2"; // AAC-LC
            case 5:
                return "mp4a.40.5"; // HE-AAC v1
            case 29:
                return "mp4a.40.29"; // HE-AAC v2
            default:
                return "unknown"; // 未知或不支持的类型
        }
    }
    analyzeAExtra(aExtra) {
        if (aExtra.length < 2) {
            console.error("aExtra data is too short.");
            return;
        }
        // 将前两个字节转换为16位整数
        const firstTwoBytes = (aExtra[0] << 8) | aExtra[1];
        // 音频对象类型占据前5位
        let audioObjectType = firstTwoBytes >> 11;
        // 采样率索引占据接下来的4位
        const samplingFrequencyIndex = (firstTwoBytes >> 7) & 0x0F;
        // 通道配置占据接下来的4位
        const channelConfig = (firstTwoBytes >> 3) & 0x0F;
        // 输出解析结果
        if (this._debug === true)
            console.log(`Audio Object Type version: ${audioObjectType}`);
        if (this._debug === true)
            console.log(`Sampling Frequency Index: ${samplingFrequencyIndex}`);
        if (this._debug === true)
            console.log(`Channel Configuration: ${channelConfig}`);
        // 根据音频对象类型确定编解码器类型
        let codecType;
        switch (audioObjectType) {
            case 2:
                codecType = "AAC-LC (Low Complexity)";
                break;
            case 5:
                codecType = "HE-AAC v1 (AAC LC + SBR)";
                break;
            case 29:
                codecType = "HE-AAC v2 (AAC LC + SBR + PS)";
                break;
            default:
                codecType = "Unknown";
        }
        console.log(`Determined Codec Type: ${codecType}`);
    }
    getStatus() {
        return this.decWorkerMgr.getStatus;
    }
    toHex(data) {
        return Array.from(data)
            .map(byte => byte.toString(16).padStart(2, '0'))
            .join(' ');
    }
}
