const DEFAULT_BUFFER_SIZE_MS = 200;
export default class JitterBuffer {
    constructor(maxSizeMs, droppedCallback) {
        this.bufferSizeMs = DEFAULT_BUFFER_SIZE_MS;
        if (maxSizeMs !== undefined && maxSizeMs > 0) {
            this.bufferSizeMs = maxSizeMs;
        }
        this.elementsList = [];
        this.droppedCallback = droppedCallback;
        this.totalLengthMs = 0;
    }
    AddItem(chunk, extraData) {
        //console.log(chunk.duration)
        let r = undefined;
        //console.log("AddItem Chunk duration", chunk.duration);
        //console.log("AddItem totalLengthMs", this.totalLengthMs);
        // TODO check and flush is more data ?
        //if (this.elementsList.length <= 0) 
        {
            this.elementsList.push({ chunk, extraData });
            this.totalLengthMs += chunk.duration / 1000;
        }
        //more than 3000ms, remove one
        if (this.elementsList.length > 3000) {
            console.log("max reached");
            this.GetItem();
        }
    }
    GetFristDuration() {
        if (this.elementsList.length <= 0) {
            return 10000;
        }
        return this.elementsList[0].chunk.duration;
    }
    GetItem() {
        let r = undefined;
        // Get 1st element if jitter buffer full
        //console.log("GetItem totalLengthMs", this.totalLengthMs);
        //if (this.totalLengthMs >= this.bufferSizeMs) 
        if (this.totalLengthMs > 0) {
            //console.log("totalLengthMs gotted", this.totalLengthMs);
            r = this.elementsList.shift();
            this.totalLengthMs -= r.chunk.duration / 1000;
        }
        return r;
    }
    GetStats() {
        return {
            totalLengthMs: this.totalLengthMs,
            size: this.elementsList.length,
        };
    }
    GetLengthMs() {
        return this.totalLengthMs;
    }
    GetOverLengthMs() {
        return this.totalLengthMs - this.bufferSizeMs;
    }
    Clear() {
        this.elementsList = [];
        this.totalLengthMs = 0;
    }
}
