export class CanvasManager {
    constructor(canvas) {
        this.canvas = canvas;
        this.shapes = [];
        this.isDrawing = false;
        this.tempShape = null;
    }
    addShape(shape) {
        this.shapes.push(shape);
        this.redraw();
    }
    startDrawing() {
        this.isDrawing = true;
    }
    stopDrawing() {
        this.isDrawing = false;
        if (this.tempShape) {
            this.addShape(this.tempShape);
            this.tempShape = null;
        }
    }
    setTempShape(shape) {
        this.tempShape = shape;
        this.redraw();
    }
    getIsDrawing() {
        return this.isDrawing;
    }
    redraw() {
        const ctx = this.canvas.getContext('2d');
        if (ctx) {
            ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
            for (const shape of this.shapes) {
                shape.draw(ctx);
            }
            if (this.tempShape) {
                this.tempShape.draw(ctx);
            }
        }
    }
    getShapes() {
        return this.shapes;
    }
    deleteShape(target) {
        const index = this.shapes.indexOf(target);
        if (index > -1) {
            this.shapes.splice(index, 1);
            this.redraw();
        }
    }
    // 添加新方法来清空画布
    clear() {
        this.shapes = []; // 清空形状数组
        this.tempShape = null; // 清空临时形状
        this.redraw(); // 重绘画布
    }
}
