//https://stackoverflow.com/questions/63639827/implementation-of-the-packbits-algorithm
export const PackBitsCompress = s => s.match(/([^])\1{1,127}|(?:([^])(?!\2)){1,128}/g).map(s => s[0] === s[1] ? String.fromCharCode(257 - s.length) + s[0]
    : String.fromCharCode(s.length - 1) + s).join("");
export function PackBitsDecompress(s) {
    let res = "";
    let i = 0;
    while (i < s.length) {
        let hdr = s.charCodeAt(i++);
        res += hdr > 128 ? s[i++].repeat(257 - hdr)
            : hdr < 128 ? s.slice(i, i += hdr + 1)
                : "";
    }
    return res;
}
