    handleMouseMove(event) {
        const mouseX = event.clientX - this.canvasManager.canvas.getBoundingClientRect().left;
        const mouseY = event.clientY - this.canvasManager.canvas.getBoundingClientRect().top;
        if (this.drawMode === DrawMode.LINE) {
            if (this.canDraw && this.isDrawing && this.startPoint) {
                const currentPoint = { x: mouseX, y: mouseY };
                let conf = {
                    point: [this.startPoint, currentPoint]
                };
                const temporaryLine = new Line(conf);
                temporaryLine.setArrowDirection(this.defaultArrowDirection);
                this.canvasManager.redraw();
                temporaryLine.draw(this.canvasManager.canvas.getContext('2d'));
            }
            else if (this.draggingEndpoint && this.highlightedLine) {
                if (this.draggingEndpoint === 'start') {
                    this.highlightedLine.setStart({ x: mouseX, y: mouseY });
                }
                else {
                    this.highlightedLine.setEnd({ x: mouseX, y: mouseY });
                }
                this.canvasManager.redraw();
            }
            else if (this.isDraggingLine && this.highlightedLine) {
                const newStart = {
                    x: this.highlightedLine.getStart().x + mouseX - (this.highlightedLine.getCenter().x + (this.dragOffset?.x || 0)),
                    y: this.highlightedLine.getStart().y + mouseY - (this.highlightedLine.getCenter().y + (this.dragOffset?.y || 0))
                };
                const newEnd = {
                    x: this.highlightedLine.getEnd().x + mouseX - (this.highlightedLine.getCenter().x + (this.dragOffset?.x || 0)),
                    y: this.highlightedLine.getEnd().y + mouseY - (this.highlightedLine.getCenter().y + (this.dragOffset?.y || 0))
                };
                this.highlightedLine.setStart(newStart);
                this.highlightedLine.setEnd(newEnd);
                this.canvasManager.redraw();
            }
            else {
                const hoveredLine = this.canvasManager.getShapes().find(shape => shape instanceof Line && shape.contains({ x: mouseX, y: mouseY }));
                if (hoveredLine) {
                    if (this.highlightedLine) {
                        this.highlightedLine.setHighlight(false);
                    }
                    hoveredLine.setHighlight(true);
                    this.highlightedLine = hoveredLine;
                    this.canvasManager.redraw();
                }
                else if (this.highlightedLine) {
                    this.highlightedLine.setHighlight(false);
                    this.highlightedLine = null;
                    this.canvasManager.redraw();
                }
            }
        }
        if (this.drawMode === DrawMode.POLYGON) {
            const hoveredPolygon = this.canvasManager.getShapes().find(shape => shape instanceof Polygon && (shape.contains({ x: mouseX, y: mouseY }) || shape.isPointOnEdge({ x: mouseX, y: mouseY })));
            // 高亮显示悬停的多边形
            if (hoveredPolygon) {
                if (this.highlightedPolygon) {
                    this.highlightedPolygon.setHighlight(false);
                }
                hoveredPolygon.setHighlight(true);
                this.highlightedPolygon = hoveredPolygon;
                this.canvasManager.redraw();
            }
            else if (this.highlightedPolygon) {
                this.highlightedPolygon.setHighlight(false);
                this.highlightedPolygon = null;
                this.canvasManager.redraw();
            }
            // 如果当前存在高亮显示的多边形，则将其设置为当前多边形
            if (this.highlightedPolygon) {
                this.currentPolygon = this.highlightedPolygon;
            }
            // 处理多边形拖动
            if (this.isDraggingPolygon && this.currentPolygon && this.dragOffset && this.selectedVertexIndex === null) {
                const dx = mouseX - this.dragOffset.x;
                const dy = mouseY - this.dragOffset.y;
                for (let i = 0; i < this.currentPolygon.getVertices().length; i++) {
                    const vertex = this.currentPolygon.getVertices()[i];
                    const updatedVertex = { x: vertex.x + dx, y: vertex.y + dy };
                    this.currentPolygon.updateVertex(i, updatedVertex);
                }
                this.dragOffset = { x: mouseX, y: mouseY };
                this.canvasManager.redraw();
            }
            // 处理顶点拖动
            else if (this.selectedVertexIndex !== null && this.currentPolygon) {
                this.currentPolygon.updateVertex(this.selectedVertexIndex, { x: mouseX, y: mouseY });
                this.canvasManager.redraw();
            }
        }
    }
    handleMouseUp(event) {
        this.isDraggingLine = false;
        this.dragOffset = null;
        const mouseX = event.clientX - this.canvasManager.canvas.getBoundingClientRect().left;
        const mouseY = event.clientY - this.canvasManager.canvas.getBoundingClientRect().top;
        if (this.drawMode === DrawMode.LINE && this.canDraw && this.isDrawing && this.startPoint) {
            const endPoint = { x: mouseX, y: mouseY };
            const length = Math.sqrt(Math.pow(endPoint.x - this.startPoint.x, 2) + Math.pow(endPoint.y - this.startPoint.y, 2));
            if (length > 20) {
                let conf = {
                    point: [this.startPoint, endPoint]
                };
                const newLine = new Line(conf);
                newLine.setArrowDirection(this.defaultArrowDirection);
                this.canvasManager.addShape(newLine);
                if (this.onShapeDrawnCallback) {
                    this.onShapeDrawnCallback();
                }
            }
            this.isDrawing = false;
            this.startPoint = null;
        } // 退出多边形的编辑模式
        else if (this.drawMode === DrawMode.POLYGON) {
            if (!this.canDraw) {
                // If not in drawing mode, check if a polygon or a vertex is selected for editing
                if (this.currentPolygon) {
                    if (this.selectedVertexIndex !== null) {
                        // Finish editing the vertex
                        this.selectedVertexIndex = null;
                        this.canvasManager.redraw();
                    }
                    else if (this.isDraggingPolygon) {
                        // Finish dragging the polygon
                        this.isDraggingPolygon = false;
                        this.dragOffset = null;
                        this.canvasManager.redraw();
                    }
                    else {
                        // If no polygon was being edited, deselect the current polygon
                        this.currentPolygon.setHighlight(false);
                        this.currentPolygon = null;
                    }
                }
            }
            else {
                // If in drawing mode, finish editing the polygon (if any)
                this.selectedVertexIndex = null;
                this.isDraggingPolygon = false;
                this.dragOffset = null;
            }
            if (this.onShapeDrawnCallback) {
                this.onShapeDrawnCallback();
            }
        }
        else {
            this.draggingEndpoint = null;
        }
    }
    handleClick(event) {
    }
