import EventEmitter from '../event-handler/event-emitter';
import WorkerDecoder from '../decoder/worker-decoder';
import Mp4Writer from '../mp4-writer/mp4-writer';
import { MediaRenderer } from '../renderer/media-renderer';
// import WebpackWorker from "worker-loader?inline=no-fallback!./worker";
//TODO h5s video and audio seq split; workerdecoder will use seq to check if wait a new I frame.
export default class WebSocketManager {
    // private worker: WebpackWorker = new WebpackWorker();
    constructor(config, videoElement) {
        this.wsSocket = null;
        this.keepaliveTimerId = null;
        this.reconnectTimerId = null;
        this.lastTimeDataRecvived = null;
        this.totalDataRecvived = BigInt(0);
        this._h264cpumode = false;
        this._jbuffersize = 300;
        this.decwo = null;
        this.renwo = null; // 添加 mediaRenderer
        this.mp4Writer = null;
        this._nSpeed = 1.0;
        this.eventEmitter = null;
        this._debug = true;
        this.config = config;
        this._videodom = videoElement;
        //console.log(config)
        if (config.consolelog != undefined) {
            if (config.consolelog === 'false') {
                this._debug = false;
            }
        }
        if (config.buffersize != undefined) {
            this._jbuffersize = config.buffersize;
        }
        if (this._debug === true)
            console.log('[WS2] buffer size:', this._jbuffersize);
        if (config.h264cpumode != undefined) {
            if (config.h264cpumode === 'true') {
                this._h264cpumode = true;
            }
        }
        if (this._debug === true)
            console.log('[WS2] h264cpumode:', this._h264cpumode);
        this.bDisConnected = false;
        this.bNeedReconnect = false;
    }
    getStatus() {
        if (this.decwo) {
            return this.decwo.getStatus();
        }
    }
    setupDecRenderWo() {
        this.closeDecRenderWo();
        this.eventEmitter = new EventEmitter();
        if (!this.decwo && this._videodom != undefined) {
            this.decwo = new WorkerDecoder(this._nSpeed, this._h264cpumode, this._jbuffersize, this._debug, this.eventEmitter, this.config.metaconf);
        }
        // 初始化和配置 mediaRenderer
        if (!this.renwo && this._videodom != undefined) {
            const videoElement = this._videodom;
            this.renwo = new MediaRenderer({ videoElement, eventEmitter: this.eventEmitter });
        }
    }
    setupMp4writer() {
        if (!this.mp4Writer) {
            this.mp4Writer = new Mp4Writer(this._debug, this.config.mp4writerconf);
        }
    }
    closeDecRenderWo() {
        try {
            if (this.eventEmitter) {
                this.eventEmitter = null;
            }
            if (this.decwo) {
                this.decwo.destory();
                delete this.decwo;
            }
            // 断开连接时销毁解码器和渲染器
            if (this.renwo) {
                this.renwo.destory();
                delete this.renwo;
            }
            if (this.mp4Writer) {
                this.mp4Writer.finish();
                delete this.mp4Writer;
            }
            this.decwo = null;
            this.renwo = null;
            this.mp4Writer = null;
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    setupWebSocket(url) {
        if (this._debug === true)
            console.log('[WS2] start connect to:', url);
        this.wsSocket = new WebSocket(url);
        this.wsSocket.binaryType = 'arraybuffer'; // 设置 binaryType 为 'arraybuffer'
        this.wsSocket.onopen = this.handleOpen.bind(this);
        this.wsSocket.onmessage = this.handleMessage.bind(this); // handleMessage 现在可以直接处理 ArrayBuffer 数据
        this.wsSocket.onclose = this.handleClose.bind(this);
        this.wsSocket.onerror = this.handleError.bind(this);
    }
    connect(url) {
        this._url = url;
        this.setupWebSocket(url);
        this.reconnectTimerId = setInterval(this.ReconnectFunction.bind(this), 3000);
    }
    start() {
        try {
            this.sendMessage({ cmd: 'H5_START' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    pause() {
        try {
            this.sendMessage({ cmd: 'H5_PAUSE' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    resume() {
        try {
            this.sendMessage({ cmd: 'H5_RESUME' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    seek(nTime) {
        try {
            this.sendMessage({ cmd: 'H5_SEEK', nSeekTime: nTime });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    moveto(strTime) {
        try {
            this.sendMessage({ cmd: 'H5_MOVETO', strMovetoTime: strTime });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    speed(nSpeed) {
        try {
            this._nSpeed = nSpeed;
            if (this.decwo) {
                this.decwo.setSpeed(nSpeed);
            }
            this.sendMessage({ cmd: 'H5_SPEED', nSpeed: nSpeed });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    handleMessage(event) {
        if (this.mp4DateTimer != null) {
            clearTimeout(this.mp4DateTimer);
        }
        if (event.data instanceof ArrayBuffer) {
            const data = new Uint8Array(event.data);
            // console.log('data',data)
            const videoData = event.data;
            //console.log(event.data.byteLength);
            this.totalDataRecvived = this.totalDataRecvived + BigInt(event.data.byteLength);
            if (this.decwo && this._videodom != undefined) {
                this.decwo.handleVideoDataReceived({ data: videoData });
            }
            if (this.mp4Writer) {
                this.mp4Writer.handleDataReceived({ data: videoData });
            }
            //this.eventEmitter.emit(EventTypes.VIDEO_DATA_RECEIVED, { data: videoData});
        }
        else {
            if (typeof event.data === 'string') {
                //if(this._debug === true) console.log("[WS2] string");
                if (this.config.pbconf != undefined && this.config.pbconf.callback != undefined) {
                    this.config.pbconf.callback(event.data, this.config.pbconf.userdata);
                }
                if (this.config.mp4writerconf != undefined && this.config.mp4writerconf.callback != undefined) {
                    this.mp4DateTimer = setTimeout(() => {
                        let data = `{
                        "type": "H5S_MP4_WRITER_FAIL"
                    }`;
                        this.config.mp4writerconf.callback(data, this.config.mp4writerconf.userdata);
                    }, 10000);
                    this.config.mp4writerconf.callback(event.data, this.config.mp4writerconf.userdata);
                }
                return;
            }
            if (this._debug === true)
                console.log('[WS2] Unexpected data type:', event.data);
        }
    }
    sendMessage(message) {
        if (this.wsSocket && this.wsSocket.readyState === WebSocket.OPEN) {
            this.wsSocket.send(JSON.stringify(message));
        }
        else {
            if (this._debug === true)
                console.log('[WS2] WebSocket is not open. Cannot send message:', message);
        }
    }
    disconnect() {
        this.bDisConnected = true;
        clearInterval(this.reconnectTimerId);
        if (this.wsSocket != null) {
            this.wsSocket.close();
            this.wsSocket = null;
        }
        this.cleanupKeepalive();
        this.closeDecRenderWo();
        if (this.mp4Writer) {
            this.mp4Writer.finish();
            this.mp4Writer = null;
        }
    }
    handleOpen(event) {
        if (this.config.pbconf != undefined && this.config.pbconf.autoplay === 'true') {
            this.start();
        }
        //console.log('ws open')
        //this.eventEmitter.emit(EventTypes.WS_OPEN, event);
        // Setup heartbeat once connection is opened
        this.setupKeepalive();
        this.setupDecRenderWo();
        if (this.config.mp4writerconf != undefined && this.config.mp4writerconf.mp4writer) {
            this.start();
            this.setupMp4writer();
        }
    }
    handleClose(event) {
        //this.eventEmitter.emit(EventTypes.WS_CLOSE, event);
        // Cleanup heartbeat on close
        this.cleanupKeepalive();
        if (this._debug === true)
            console.log("[WS2] wsSocket.onclose");
        if (this.bDisConnected === true) {
            if (this._debug === true)
                console.log("[WS2] wsSocket.onclose disconnect");
        }
        else {
            this.bNeedReconnect = true;
        }
        this.closeDecRenderWo();
    }
    handleError(event) {
        //this.eventEmitter.emit(EventTypes.WS_ERROR, event);
    }
    setupKeepalive() {
        this.keepaliveTimerId = setInterval(this.keepaliveTimer.bind(this), 5000);
    }
    keepaliveTimer() {
        if (this.lastTimeDataRecvived != null) {
            if (this.totalDataRecvived <= this.lastTimeDataRecvived) {
                if (this.config.pbconf === undefined && this.config.mp4writerconf === undefined) {
                    //live
                    if (this._debug === true)
                        console.log('[WS2] no data received reconnect...');
                    this.bNeedReconnect = true;
                    this.closeDecRenderWo();
                    if (this.wsSocket) {
                        this.wsSocket.close();
                        this.wsSocket = null;
                    }
                    return;
                }
                else {
                    //playback
                }
            }
        }
        this.lastTimeDataRecvived = this.totalDataRecvived;
        try {
            this.sendMessage({ cmd: 'H5_KEEPALIVE' });
        }
        catch (e) {
            if (this._debug === true)
                console.log(e);
        }
    }
    ReconnectFunction() {
        if (this.bNeedReconnect === true) {
            if (this._debug === true)
                console.log('[WS2] Reconnect...');
            //TODO update image url
            //var strReconnectUrl = this._strPosterUri + "&update=" + this._nReconnectCnt;
            //this._videodom.setAttribute('poster', strReconnectUrl);
            //if(this._debug === true) console.log('[WS2] Reconnect image', strReconnectUrl);
            //this._nReconnectCnt++;
            //console.log(this);
            this.lastTimeDataRecvived = null;
            this.totalDataRecvived = BigInt(0);
            this.setupWebSocket(this._url);
            this.bNeedReconnect = false;
        }
    }
    cleanupKeepalive() {
        if (this.keepaliveTimerId !== null) {
            //console.log("cleanupKeepalive")
            clearInterval(this.keepaliveTimerId);
            this.keepaliveTimerId = null;
        }
    }
}
